fn search_insert(xs: &Vec<i32>, target: i32) -> usize {
    // We maintain a search window [left, right) over possible insertion indices.
    let mut left = 0;
    let mut right = xs.len();

    while left < right {
        // Avoid overflow; mid is always within [left, right).
        let mid = left + (right - left) / 2;

        // If xs[mid] is still less than target, the insertion point must be to the right of mid.
        if xs[mid] < target {
            left = mid + 1;
        } else {
            // xs[mid] >= target, so the insertion point is at or before mid.
            right = mid;
        }
    }

    // When left == right, we've found the smallest index k such that
    // all xs[0..k] < target and (k == xs.len() or target <= xs[k]).
    left
}

